text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "项目任务整体概况",
      "business_question": "这份项目任务数据中，总共有多少条记录？涉及多少个不同的项目和状态？工时字段的缺失情况如何？",
      "priority": "P0",
      "priority_reason": "探索性分析的基础，提供数据集的整体规模和关键维度的多样性概览，是理解后续分布差异的前提。删除此任务将无法回答“主要分布”中的基础构成问题。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_tasks"
              },
              {
                "function": "distinct_count",
                "field": "field_0002",
                "alias": "unique_projects"
              },
              {
                "function": "distinct_count",
                "field": "field_0003",
                "alias": "unique_statuses"
              },
              {
                "function": "count",
                "field": "field_0004",
                "alias": "non_missing_hours"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "按项目分布的任务数量与工时统计",
      "business_question": "不同项目下的任务数量分别是多少？各项目的平均工时、最高工时和最低工时有何差异？",
      "priority": "P0",
      "priority_reason": "直接响应“主要分布与差异”的核心需求，通过分组聚合揭示项目维度上的资源（任务数）和投入（工时）分布特征。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_hours"
              },
              {
                "function": "max",
                "field": "field_0004",
                "alias": "max_hours"
              },
              {
                "function": "min",
                "field": "field_0004",
                "alias": "min_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "按状态分布的任务数量与工时统计",
      "business_question": "不同任务状态下的任务数量分别是多少？各状态的平均工时是多少？是否存在特定状态下工时显著偏高或偏低的情况？",
      "priority": "P0",
      "priority_reason": "从状态维度探索数据的分布差异，帮助识别工作流瓶颈或异常负载，补充项目维度之外的另一主要分类视角。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_hours"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T04",
      "title": "按创建日期年份的任务分布趋势",
      "business_question": "任务主要集中在哪些年份创建？不同年份的任务数量和平均工时是否有明显变化？",
      "priority": "P1",
      "priority_reason": "时间维度是探索数据规律的重要补充。虽然只有8行数据且日期唯一，但提取年份有助于快速判断数据的时间跨度及是否集中在特定时段，为后续可能的季节性分析提供初步依据。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "derive",
          "params": {
            "function": "extract_year",
            "field": "field_0001",
            "alias": "creation_year"
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_hours"
              }
            ],
            "dimensions": [
              "creation_year"
            ]
          }
        }
      ]
    }
  ]
}
